globalThis.__IT_TREND_EMBEDDED_DATA__ = {"updated_at":"2026-11-18 07:07:11 JST","total_count":50,"config":{"selected_genres":["ai","web","infra","mobile","biz"],"other_genre_min_ratio":0.25,"max_age_hours":72.0,"genres":{"ai":"AI・LLM・機械学習","web":"Web開発・言語","infra":"インフラ・クラウド・セキュリティ","mobile":"モバイル・ガジェット・個人開発","biz":"ITビジネス・キャリア・マネジメント","other":"総合・その他IT"}},"articles":[{"title":"楽天証券に不正アクセス、最大1125万口座のIDなど漏えいか　最大447万口座は金融資産情報も","url":"https://www.itmedia.co.jp/news/article/2611/17/2000003275/","source":"Hatena","published_at":"2026-11-17 19:45","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"楽天証券で不正アクセス発生、最大1125万口座の個人情報漏洩の恐れ","summary":"楽天証券は、第三者による不正アクセスにより、最大約1125万口座分のログインIDなどが漏洩した可能性があると発表しました。うち最大約447万口座分については、氏名、住所、年収、金融資産情報なども含まれる可能性があります。\n\n原因はテスト環境のシステム管理不備とされており、本番データがテスト環境に混入していたことが指摘されています。パスワードや暗証番号の漏洩は確認されておらず、現時点で不正取引も報告されていませんが、同社は対象者への個別連絡とセキュリティ対策の強化を進めています。","importance":10},{"title":"NVIDIA、CEO 交代に関するお知らせ","url":"https://blogs.nvidia.co.jp/blog/nvidia-announces-ceo-transition/","source":"Hatena","published_at":"2026-11-17 15:39","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"NVIDIAのジェンスン・フアンCEOが辞任、暫定CEOにコレット・クレス氏","summary":"NVIDIAは、ジェンスン・フアン氏が社長兼CEOおよび取締役を即時辞任したと発表。後任が決定するまで、CFOのコレット・クレス氏が暫定CEOを務める。\n\n取締役会は正式なCEOの選定を開始した。クレス氏は財務部門を率いてきた実績があり、経営陣と共に戦略の実行と製品ロードマップの推進を継続する。業界に多大な影響を与えたフアン氏の退任は、今後のAI市場の動向に大きな注目を集めている。","importance":10},{"title":"LiteRT-LM on Android 実装Tips — 実機 10 数機種で分かったこと","url":"https://zenn.dev/uphyca/articles/ab08a82829d5aa","source":"Zenn","published_at":"2026-11-18 02:08","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"AndroidでのLiteRT-LM実装：実機検証で判明したキャッシュと発熱の注意点","summary":"AndroidアプリでオンデバイスLLM（LiteRT-LM）を実装する際の技術的知見をまとめた記事。実機10数機種での検証を通じ、初回のモデル読み込みが極端に遅い問題や、キャッシュ管理の難しさ、端末の発熱による性能低下といった課題への対策を提示しています。\n\n特に、モデルダウンロード直後のキャッシュ事前生成や、バックエンドごとのキャッシュディレクトリ分離によるストレージ節約、会話ごとのConversation再生成といった具体的な実装Tipsが共有されており、実用的なLLMアプリ開発の参考になります。","importance":8},{"title":"メルカリ、Google Play ストアでアプリが検索・ダウンロードできない状態に","url":"https://www.itmedia.co.jp/news/article/2611/17/2000003274/","source":"Hatena","published_at":"2026-11-17 19:58","genre":"other","genre_label":"総合・その他IT","headline":"メルカリがGoogle Playストアから一時的に検索・ダウンロード不可に","summary":"11月17日午後6時40分ごろから、Google Playストアにてフリマアプリ「メルカリ」が検索およびダウンロードできない状態となりました。Webブラウザからアクセスしてもページが見つからないエラーが表示される状況です。\n\nメルカリ社は現在原因を調査中としており、ユーザーに対しては既にインストール済みのアプリを削除しないよう呼びかけています。詳細な原因や復旧の見通しについては、今後の公式発表が待たれます。","importance":6},{"title":"Faster type-aware linting with tsrs","url":"https://oxc.rs/blog/2026-11-17-faster-type-aware-linting-with-tsrs","source":"Hatena","published_at":"2026-11-18 01:08","genre":"web","genre_label":"Web開発・言語","headline":"OxlintにRust製「tsrs」を統合、型チェックとLintの高速化を実現","summary":"JavaScript/TypeScriptツールチェーン「Oxlint」に、Rustで再実装されたTypeScriptエンジン「tsrs」が統合されたことを紹介。これにより、従来のtsgolintと比較して最大7倍の高速化とメモリ使用量の75%削減を実現しています。\n\ntsrsは型情報を考慮したLint（type-aware linting）を高速に行うためのバックエンドとして機能し、既存のOxlint設定をそのまま利用可能です。CIや開発環境でのフィードバックループを大幅に短縮できるため、大規模プロジェクトにおける開発体験の向上が期待されます。","importance":8},{"title":"人型ロボットに人間の動きを学習させるためのAI「GR00T 2」をNVIDIAが発表、数回のお手本からタスクを学べる","url":"https://gigazine.net/news/20261117-nvidia-robot-gr00t-2/","source":"Hatena","published_at":"2026-11-17 18:07","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"NVIDIAが人型ロボット用AI「GR00T 2」を発表、数回のデモで学習可能","summary":"NVIDIAは、人型ロボットを操作するための世界行動モデル「GR00T 2」を発表しました。人間の動作動画や遠隔操作データで事前学習されており、わずか5回のデモンストレーションで新たなタスクを学習可能です。\n\nGeForce RTX 5090を用いて30分で学習、推論まで実行できる高い効率性を備えています。全身を使った複雑な家事動作や、他のAIモデルと連携したタスク遂行も可能で、汎用ロボット開発の大きな進歩として期待されています。関連コードは12月に公開予定です。","importance":9},{"title":"楽天証券が不正アクセスを受け最大約1125万口座分のログインIDなどが漏えい、さらにエンジニア3日の人でもヤバいと分かる行為をやっていたことが判明","url":"https://togetter.com/li/2771595","source":"Hatena","published_at":"2026-11-17 19:31","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"楽天証券の個人情報漏洩、テスト環境への本番データ利用が物議","summary":"楽天証券の不正アクセスによる大規模な個人情報漏洩事案において、テスト環境で本番データが管理されていたことがエンジニア界隈で大きな批判を浴びています。最大1125万口座のログインIDや、447万口座の詳細な個人情報が流出した恐れがあります。\n\nセキュリティ基準においてテスト環境での本番データ利用は厳禁とされる中、今回の事態は企業のセキュリティガバナンスに対する深刻な疑念を招いています。同社はパスキー認証の推奨や取引の一時停止機能などを案内し、再発防止に向けた対応を急いでいます。","importance":10},{"title":"推定量と推定値は何が違うのか","url":"https://zenn.dev/pillow_stat/articles/statistic-estimator-estimate","source":"Zenn","published_at":"2026-11-17 22:26","genre":"other","genre_label":"総合・その他IT","headline":"統計学における「推定量」と「推定値」の明確な違いと使い分け","summary":"統計学の頻度論の立場から、確率変数である「推定量」と、データから算出された具体的な数値である「推定値」の違いを解説。標本分布や信頼区間の概念を交え、両者を混同しやすい場面を整理しています。\n\n数式や文脈が「データを取る前（確率変数）」か「取った後（実現値）」かを判断基準にすることで、統計学の概念を正しく理解するための指針を提示。統計的な推論を行う上で不可欠な基礎知識を、図解を交えて論理的に説明しています。","importance":5},{"title":"5年前に自分で歌った曲がAI音楽企業の著作権侵害申し立てで削除される、異議申し立ても2回却下","url":"https://gigazine.net/news/20261117-musician-copyright-hell/","source":"Hatena","published_at":"2026-11-17 18:17","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"AI音楽企業の自動削除システムによる著作権侵害申し立ての弊害","summary":"ミュージシャンが自身の歌声をYouTubeに投稿したところ、AIを活用する音楽配信企業から著作権侵害の申し立てを受け、動画が削除されるトラブルが発生しました。異議申し立ても2回却下されるなど、自動化された権利保護システムの弊害が浮き彫りとなりました。\n\n問題の企業はAIを用いて大量の楽曲を識別し、自動的に削除申請を行っていましたが、実際には権利を持たない範囲まで削除を要求していました。メディアの介入により動画は復活しましたが、人間による確認プロセスが欠如したシステム全体への不信感が強まっています。","importance":7},{"title":"ChatGPTやClaudeがMacを操作する時代に--Appleが「macOS 27.3」で対応強化","url":"https://japan.cnet.com/article/35254992/","source":"Hatena","published_at":"2026-11-17 14:32","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"macOS 27.3でAIエージェントの操作権限管理を強化","summary":"Appleは「macOS 27.3」ベータ2にて、AIエージェントによるMac操作やデータアクセス権限を細かく管理する新機能を発表。利用者の許可範囲を明確化する。\n\n「Device Control and Data Access」を分割し、アプリごとの操作許可やアクセス範囲を限定可能にする。また、AIが他アプリを操作している際の表示機能を追加し、透明性を高める。AIエージェントの自律化に伴うセキュリティリスクを低減するための重要なアップデートである。","importance":8},{"title":"決済という機能を実装するのは容易だが、思っていたより考えることが多かった","url":"https://zenn.dev/chot/articles/1297582ee96341","source":"Zenn","published_at":"2026-11-17 20:22","genre":"web","genre_label":"Web開発・言語","headline":"決済機能実装における二重決済や不正防止の設計指針","summary":"決済機能はサービスの信用を左右する重要な責務を担うため、単なるAPI呼び出し以上の慎重な設計が求められます。金額の改ざん防止、在庫確保の整合性、冪等性の確保、タイムアウト時の状態管理など、考慮すべきエッジケースは多岐にわたります。\n\n特に、通信障害時の二重課金防止や、注文・決済・商品提供のステータス管理を分離する設計が重要です。決済成功と商品提供の失敗を区別し、再処理可能な状態を保つことで、ユーザー体験と信頼性を維持する堅牢な決済システムを構築できます。","importance":8},{"title":"メンテナンスモードだったはずでは？ 「Adobe Animate 2027」で懐かしFlashアニメが！／約3年ぶりの機能追加、2Dの絵をAIで回せるターンテーブルを搭載【やじうまの杜】","url":"https://forest.watch.impress.co.jp/docs/serial/yajiuma/2157125.html","source":"Hatena","published_at":"2026-11-17 18:23","genre":"other","genre_label":"総合・その他IT","headline":"Adobe Animate 2027が約3年ぶりにアップデート、生成AI機能を搭載","summary":"メンテナンスモードに入っていた「Adobe Animate」が、約3年ぶりの機能追加となる「Animate 2027」としてアップデートされました。2DイラストをAIで回転・傾斜させる「ターンテーブル」機能が新たに搭載されています。\n\nAdobe Fireflyの生成AIを活用し、ステージ上のオブジェクトから別角度のビューを生成することで、アニメ制作の効率化を図ります。他にもコンテンツクレデンシャルの付与やUIの刷新が行われており、かつてのFlashアニメファンからも注目を集めています。","importance":5},{"title":"ローカルLLM入門","url":"https://zenn.dev/port_inc/articles/ff974c7456f4db","source":"Zenn","published_at":"2026-11-17 16:17","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"ローカルLLMの仕組みと推論速度を決定づける技術的要因","summary":"ローカルLLMの仕組みとして、モデルの重み、推論エンジン、メモリ帯域の重要性を解説。PCでLLMを動かすための技術的背景と、推論速度のボトルネックについて整理した。\n\nLLMの推論速度は計算性能よりもメモリ帯域に依存し、特にDecodeフェーズではデータ転送速度が上限を決める。最新のハードウェア環境での実測値や、WebGPUを用いたブラウザ実行の可能性など、ローカル環境でAIを運用するための実践的な知見がまとめられている。","importance":9},{"title":"楽天証券に不正アクセス、最大1125万口座のログインIDなど漏えいのおそれ（CNET Japan） - Yahoo!ニュース","url":"https://news.yahoo.co.jp/articles/141fe69b0f33952604cde710494bbdff584f269a","source":"Hatena","published_at":"2026-11-17 18:33","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"楽天証券、不正アクセスにより最大1125万口座のログインID漏洩の可能性","summary":"楽天証券は11月17日、第三者による不正アクセスを受け、最大約1125万口座のログインIDなどが外部に漏洩した可能性があると発表しました。最大約447万口座については、氏名や住所、金融資産情報なども対象となっています。\n\n11月16日に不正アクセスを検知し、調査の結果、11月11日にテスト環境で管理されていた情報が流出したことが判明しました。パスワードや暗証番号の漏洩は確認されておらず、不正取引も現時点では報告されていません。同社は影響を受けた顧客への個別連絡と、パスキー認証の設定を強く推奨しています。","importance":10},{"title":"お問い合わせの8割を、AIボットが解決するようになった話","url":"https://zenn.dev/rimo/articles/701d18b7764669","source":"Zenn","published_at":"2026-11-17 10:05","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"RAGと過去ログ活用によるAIボットのお問い合わせ自動化","summary":"Rimoでは、増え続けるカスタマーサポートの問い合わせに対応するため、社内のRAG基盤を応用した内製AIボットを導入しました。ヘルプ記事の検索に加え、契約プランの照合や過去の問い合わせ要約を参照することで、精度の高い回答を実現しています。\n\nさらに、ボットがユーザーの処理状況を確認し、必要に応じて議事録生成の再実行を行うなど、単なる回答以上の踏み込んだ支援を可能にしました。内製化により改善サイクルを自律的に回せるようになり、現在では問い合わせの約8割をボットが解決しています。","importance":7},{"title":"Go Conference 2026実行委員を終えて","url":"https://zenn.dev/mire0726/articles/1f3f118662a0f5","source":"Zenn","published_at":"2026-11-17 16:21","genre":"other","genre_label":"総合・その他IT","headline":"Go Conference 2026運営の振り返りとAI時代のカンファレンス","summary":"Go Conference 2026の実行委員が、持続可能な運営と学生支援、プロポーザル採択基準の刷新について振り返った。AI時代におけるカンファレンスの価値を再定義し、運営体制を強化した。\n\nAIによる情報収集が容易になる中、カンファレンスでは具体的で明確なセッション内容を重視する方針へ転換。また、Discordの活用や学生スタッフの能動的な参加により、コミュニティの活性化を実現した。次年度に向けた運営の引き継ぎと、持続的なイベント作りの知見が共有されている。","importance":5},{"title":"👂会議を日本語の教科書にする：聞き取れなかった言葉をその場で解説し、自分のレベルに合わせて復習するアプリを作った","url":"https://zenn.dev/u_zero/articles/32b5c208d60be2","source":"Zenn","published_at":"2026-11-17 16:30","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"会議の文字起こしを教材化し、その場で語彙を習得する学習アプリ","summary":"日本語を母語としないエンジニアが、日々の会議を効率的な学習教材に変えるアプリ「kotoba-mimi」を開発した。会議の文字起こしデータを活用し、不明な単語をその場で解説・復習できる仕組みを構築している。\n\n会議中に聞き取れなかった単語をリアルタイムで解説し、文脈と共に記憶に定着させる。辞書とClaudeを組み合わせた解説機能や、習熟度に応じた小テスト、会議の文脈を活かした復習機能により、実務で直面する「生きた日本語」を効率的に習得できる点が特徴である。","importance":7},{"title":"内製 Background Agent “haro”に アラート対応を任せたら 回すたびに賢くなっていった - LayerX エンジニアブログ","url":"https://tech.layerx.co.jp/entry/haro-alert-loop","source":"Hatena","published_at":"2026-11-17 13:20","genre":"web","genre_label":"Web開発・言語","headline":"内製エージェント「haro」によるアラート対応の自動化と改善","summary":"LayerXのエンジニアが、内製Background Coding Agent「haro」を用いてアラート対応を自動化した事例を紹介。巡回から調査、PR作成までをエージェントが担う。\n\nアラートノイズを自動で振り分け、既知の事象はWikiを参照して判定する仕組みを構築。3週間半の運用で多くの調査ページと修正PRが作成され、エンジニアの負担軽減と対応の標準化を実現した。エージェントが自ら調査手順を学習・更新する仕組みが特徴である。","importance":7},{"title":"OpenAIが児童ポルノ検出ツールを開発し監視団体に提供開始","url":"https://gigazine.net/news/20261117-openai-child-safety/","source":"Hatena","published_at":"2026-11-17 14:06","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"OpenAIが児童ポルノ検出ツールを開発し監視団体へ無償提供","summary":"OpenAIは、AI生成画像を含む児童性的虐待コンテンツ（CSAM）を検出する新しい分類器を開発し、監視団体へ無償提供を開始した。ChatGPTへの警告機能強化も併せて実施する。\n\n新ツールは既存の保護機能と同等の検出精度を維持しつつ、誤検出を大幅に削減できる。また、ChatGPTで有害なコンテンツ生成を試みたユーザーに対し、警告表示やアクセス停止措置を講じるなど、児童保護に向けた安全対策を包括的に強化している。","importance":9},{"title":"LTを盛り上げよう！AWSサービス応援うちわ制作裏話","url":"https://zenn.dev/namiki64/articles/7aab23e02d1dc4","source":"Zenn","published_at":"2026-11-17 12:55","genre":"other","genre_label":"総合・その他IT","headline":"LTイベントを盛り上げる「AWSサービス応援うちわ」制作の裏話","summary":"JAWS-UG大阪のLTイベントにて、参加者の推しサービスを応援するための「応援うちわ」を制作した事例。AIを活用したフレーズ考案からデザインまで、制作プロセスを公開する。\n\nアイドル文化の「推し活」を技術コミュニティに取り入れ、各サービスの特徴を捉えたキャッチーなフレーズをAIで生成。LTイベントの盛り上げに貢献した。技術的な内容を親しみやすく表現するための工夫や、AIとの協働によるクリエイティブな試みがまとめられている。","importance":4},{"title":"当社お客様の情報漏えいの可能性に関するお詫びとお知らせ:楽天証券","url":"https://www.rakuten-sec.co.jp/web/info/info20261117-02.html","source":"Hatena","published_at":"2026-11-17 17:41","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"楽天証券、不正アクセスによる情報漏洩の可能性を公式発表","summary":"楽天証券は、第三者による不正アクセスにより顧客情報の一部が漏洩した可能性があることを公式に発表しました。テスト環境で管理していた情報が流出したもので、ログインIDや氏名、住所、金融資産情報などが対象となっています。\n\nパスワードや暗証番号の漏洩は確認されておらず、不正取引も現時点では発生していません。同社は影響を受けた顧客へ個別に報告を行うとともに、パスキー認証の利用や取引の一時停止機能の活用を呼びかけています。再発防止に向けたセキュリティ対策の強化が急務となっています。","importance":10},{"title":"「BtoBマーケティングなら才流」と言われるまでの一連の取り組みを解説 | 社長ブログ | 才流","url":"https://sairu.co.jp/blog/110447/","source":"Hatena","published_at":"2026-11-17 16:04","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"BtoBマーケティングで「第一想起」を獲得した才流の戦略","summary":"BtoBマーケティング支援で高い認知度を誇る「才流」が、ブランド構築のために実施した3つのフェーズと共通の重要ポイントを解説。発信基盤の構築から権威性の確立までを振り返る。\n\n競合が少ないチャネルの選定、インフルエンサーとの連携による流通経路の設計、そして経営者による継続的な発信が成功の鍵となった。特定のセグメントで「第一想起」を獲得するための、戦略的なコンテンツマーケティングの知見が示されている。","importance":6},{"title":"自動でクレーンのようにモノをつかんで部屋をお片付けしてくれるオープンソースロボット「Stringman」","url":"https://gigazine.net/news/20261117-stringman-cable-robot/","source":"Hatena","published_at":"2026-11-17 22:35","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"部屋の片付けを自動化するオープンソースロボット「Stringman」の仕組み","summary":"天井の四隅から伸びたラインでグリッパーを吊り下げ、クレーンのように部屋を移動してモノを片付けるオープンソースロボット「Stringman」を紹介。4つのモーターでグリッパーを制御し、カメラとマーカーで位置を推定する仕組みにより、低コストかつ高精度な自動化を実現しています。\n\nAIによる物体認識とタグ付けによる運び先指定により、衣類やおもちゃの回収を自動化。障害物回避機能は未実装ながら、家庭内での自動化プロジェクトとして非常に野心的で、ハードウェアとソフトウェアの統合的な設計が参考になります。","importance":6},{"title":"Claude Desktop 開発のすゝめ","url":"https://zenn.dev/peoplex_blog/articles/vscode-to-claude-desktop","source":"Zenn","published_at":"2026-11-17 12:41","genre":"web","genre_label":"Web開発・言語","headline":"VS CodeからClaude Desktopへ移行した開発環境の最適化","summary":"フロントエンドエンジニアが、VS CodeからClaude Desktopへ開発環境を完全に移行した理由と、並行セッション管理のノウハウを解説する。\n\nサイドバーでのセッション管理の視認性の高さや、エージェントの統合により、自作の通知ツールなしで5〜10個のセッションを並行運用できるようになった。CLIでのエージェント呼び出しと純正アプリの組み合わせにより、開発効率を最大化する現代的なワークフローが示されている。","importance":7},{"title":"Forms の自動回答を Claudeにやらせる","url":"https://zenn.dev/ai_daigakusei/articles/microsoft-forms-draft-fill-human-submits","source":"Zenn","published_at":"2026-11-18 02:38","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Claude Codeを活用したMicrosoft Formsの自動回答・下書き作成ツール","summary":"Microsoft Formsの設問を読み取り、Claude Codeを用いて回答の下書きを自動生成・入力する仕組みの解説記事。フォームの設問をJSON化し、AIが回答を生成してブラウザ上のフォーム欄に自動入力するスクリプトの構築方法を紹介しています。\n\n送信ボタンはあえて自動化せず、ユーザーが最終確認を行う設計にすることで誤送信を防ぐ安全性を確保。また、回答困難な設問をTelegram経由でスマホに通知する機能も実装しており、単純作業の効率化とAIによる補助を両立させる実用的な自動化手法です。","importance":7},{"title":"楽天証券から漏洩した情報とは？　テスト環境に一時的に置いた顧客データを狙われたか（山口健太） - エキスパート - Yahoo!ニュース","url":"https://news.yahoo.co.jp/expert/articles/a46f1f27a0870d14588ebdbaa074fb457c0d95b3","source":"Hatena","published_at":"2026-11-18 00:13","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"楽天証券のテスト環境から顧客データ漏洩：原因とセキュリティの教訓","summary":"楽天証券のテスト環境に対する不正アクセスにより、最大約1572万口座の顧客情報が漏洩した可能性について解説。テスト環境に本番データが一時的に置かれていたことが原因であり、開発・ステージング環境におけるデータ管理の不備が浮き彫りとなりました。\n\n本番環境と同等のセキュリティ対策がテスト環境に適用されていなかった点や、攻撃者がサーバーを特定した手法など、組織的なセキュリティガバナンスの重要性が問われる事案です。フィッシング対策としてのパスキー導入状況や、ログインID変更の検討など、今後の対応についても触れています。","importance":9},{"title":"カンファレンスノベルティの話から考える、技術カンファレンスの続け方 - 941::blog","url":"https://blog.kushii.net/archives/2026/11/17/211328","source":"Hatena","published_at":"2026-11-17 21:15","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"技術カンファレンスのノベルティ論から見る、持続可能な運営のあり方","summary":"技術カンファレンスにおけるノベルティの必要性という議論を起点に、イベント運営の収支構造やスポンサーシップの価値について考察。参加費無料の裏側にあるスポンサーの負担と、主催者が提供すべき価値の変遷を解説しています。\n\n単なるロゴ掲出から、参加者との深い交流へとスポンサー特典が進化している現状を指摘。ノベルティの是非だけでなく、コミュニティの持続可能性を確保するために、主催者とスポンサーが共に価値を創造する重要性を説いています。イベント運営者にとって示唆に富む内容です。","importance":5},{"title":"Google日本語入力が不満な人へ、Windows/Mac対応国産ソフト「もずきー」登場。遅延付きライブ変換とAI文脈補正を搭載、使うほど学習し自分好みに（生成AIクローズアップ） | テクノエッジ TechnoEdge","url":"https://www.techno-edge.net/article/2026/11/17/5737.html","source":"Hatena","published_at":"2026-11-17 09:51","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"ローカルAI文脈補正を搭載した日本語入力ソフト「もずきー」","summary":"「Mozkey（もずきー）」は、Google日本語入力のオープンソース版「Mozc」をベースにした、Windows/Mac対応の日本語入力ソフトです。最大の特徴は、遅延付きライブ変換とローカルAI「Zenz」による文脈補正を組み合わせている点です。\n\nAIが前後の文脈を読み取り、同音異義語の使い分けや自然な助詞のつながりを自動で整えます。プライバシーに配慮したローカルファースト設計であり、外部通信を行わずにAI処理が完結します。学習機能も備えており、ユーザーの入力傾向に合わせて変換精度が向上する仕組みです。","importance":6},{"title":"AIが時代遅れのWebサイトを書くのを防ぐスキル「Modern Web Guidance」が安定版に／「Edge」「Firefox」も参加、Webサイトのモダナイズにも","url":"https://forest.watch.impress.co.jp/docs/news/2156904.html","source":"Hatena","published_at":"2026-11-17 10:04","genre":"web","genre_label":"Web開発・言語","headline":"AIコーディング支援スキル「Modern Web Guidance」v1.0リリース","summary":"Googleが開発した「Modern Web Guidance」v1.0が安定版としてリリースされました。これはAIコーディングエージェントに対し、最新のWeb開発手法やブラウザ互換性の知識を付与するスキル集です。既存コードを解析し、最新のHTML/CSSへの置き換えを提案するワークフローが追加されました。\n\n今回のバージョンではChromeに加え、EdgeやFirefoxもプロジェクトに参加し、クロスブラウザ対応が強化されました。主要なコーディングエージェントのプラグインとして導入可能で、Chrome DevTools for agentsとの併用により、Webサイトのモダナイズを効率的に進められます。","importance":7},{"title":"【WAM】Praxis-1 を公開コードで動かしてみた","url":"https://zenn.dev/dxclab/articles/7a5ab11ae37082","source":"Zenn","published_at":"2026-11-17 23:38","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Runwayのロボット方策モデル「Praxis-1」をシミュレータで検証","summary":"Runwayが公開した動画生成モデルベースのロボット方策モデル「Praxis-1」の検証記録。VLA（Vision-Language-Action）モデルとは異なり、未来の映像を予測するWorld Action Model（WAM）を採用している点が特徴です。\n\nA100 GPU環境で公開コードと重みを動かし、MuJoCoシミュレータ上でタスクを実行した結果、高い成功率を確認。推論時の計算コストや動作の仕組みを整理し、VLAとのアーキテクチャ上の違いを明確に解説しています。次世代のロボット制御技術として注目されるWAMの理解に役立つ記事です。","importance":8},{"title":"マイクロソフトの幹部、大規模障害を引き起こした3つの原因を公表","url":"https://japan.zdnet.com/article/35254976/","source":"Hatena","published_at":"2026-11-17 15:00","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"Microsoft大規模障害、アップデートの欠陥と負荷の連鎖が原因","summary":"Microsoft 365などで発生した大規模障害の原因が、ネットワークゲートウェイのアップデートに潜んでいた欠陥と、トラフィックの急増による連鎖的な過負荷であったことが判明した。\n\nテスト環境と本番環境の構成差異により欠陥が見逃され、特定の負荷条件下でロック競合が発生した。さらに、フェイルオーバーによるトラフィック集中が障害を拡大させた。Microsoftは自動復旧プロセスの設計見直しなど、再発防止に向けた取り組みを進めている。","importance":9},{"title":"GitHub - krisgfx9/Wireless-Device-Battery-Monitor: Show the battery level of wireless mice, headsets, keyboards and controllers on the Windows 10/11 taskbar. Lightweight tray app, no vendor software needed. Supports Logitech, Razer, SteelSeries, Corsair,","url":"https://github.com/krisgfx9/Wireless-Device-Battery-Monitor","source":"Hatena","published_at":"2026-11-17 21:00","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"Windowsタスクバーで無線デバイスの電池残量を確認できる軽量アプリ","summary":"マウスやキーボード、コントローラーなどの無線デバイスの電池残量をWindowsタスクバーに表示するオープンソースの軽量アプリ「Wireless Battery Monitor」を紹介。メーカー独自の重い管理ソフトをインストールすることなく、直接デバイスと通信して残量を取得します。\n\nC++/Win32で書かれた約350KBの軽量設計で、メモリ消費も少なく、バックグラウンドサービスも不要。主要なゲーミングデバイスブランドやBluetoothデバイスを幅広くサポートしており、PC環境をクリーンに保ちたいユーザーにとって非常に実用的なツールです。","importance":5},{"title":"glTF/GLBの内部構造とSkeletal Animationの仕組み","url":"https://zenn.dev/otinpan/articles/069d728ded395d","source":"Zenn","published_at":"2026-11-17 20:29","genre":"web","genre_label":"Web開発・言語","headline":"glTF/GLBの内部構造とSkeletal Animationの仕組みを解説","summary":"3DデータフォーマットglTF（GLB）の構造と、スケルタルアニメーションの仕組みを解説。JSONによる定義とバイナリデータ（頂点、スキニング情報、キーフレーム）の分離構造を紐解き、ゲームエンジンへの実装に必要な知識を整理しています。\n\n特に、頂点と関節の関連付け（Skinning）や、Inverse Bind Matrixの役割、アニメーションデータの格納形式について詳細に記述。OBJ形式との違いを明確にし、現代的な3Dフォーマットの標準であるglTFの理解を深めるための技術資料として優れています。","importance":6},{"title":"Google「Gemini Notebook」、業務ツールを生成できる新機能","url":"https://japan.cnet.com/article/35254996/","source":"Hatena","published_at":"2026-11-17 16:22","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Gemini Notebookが資料から操作可能なWebサイトを自動生成","summary":"GoogleはAIノートツール「Gemini Notebook」に、取り込んだ資料を基に操作可能なWebサイトを生成する新機能を追加した。学習教材や売上ダッシュボード、タスク管理ツールなどをチャット指示だけで作成できる。\n\nユーザーは「サイトを作って」と指示するだけで、資料の内容を反映したWebサイトが生成される。生成されたサイトはブラウザで操作・共有が可能で、今後はモバイルアプリ版への導入も予定されている。業務効率化や学習支援ツールとしての活用が期待される。","importance":8},{"title":"WSL2を入れたWindows 11でRealtekの有線LANが止まる：nt_rtf64を外すまでの切り分け（HP OMEN 35L）","url":"https://zenn.dev/fieldtech/articles/wsl2-realtek-nt-rtf64-ethernet-stops","source":"Zenn","published_at":"2026-11-18 00:18","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"WSL2環境でRealtek有線LANが停止する問題の切り分けと解決策","summary":"Windows 11上のWSL2環境において、Realtek製NICの送信が停止する不具合の調査記録。ネットワーク構成の変更（RasMan起動など）が引き金となり、ドライバのフィルタ「nt_rtf64」がパケット処理を阻害していることを突き止め、これを無効化することで解決に至った経緯を詳述しています。\n\nライブダンプを用いたWinDbgによる解析や、仮想NICと物理NICの競合調査など、高度なトラブルシューティング手法が示されています。WSL2利用時のネットワークトラブルに悩むエンジニアにとって非常に有益な知見です。","importance":7},{"title":"SWITCHBOT、オールシーズン温度を自動調整する「moera スマートマットレストッパー」を発表","url":"https://k-tai.watch.impress.co.jp/docs/news/2157234.html","source":"Hatena","published_at":"2026-11-17 19:59","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"SwitchBot、温度自動調整機能を備えたスマートマットレストッパーを発表","summary":"SwitchBotは、ベッドの温度を自動調整する「moera スマートマットレストッパー」を発表しました。マットレスの上に敷いて使用するデバイスで、内部で加温または冷却した水を循環させることで、最大49度から最低10度までの温度調整が可能です。\n\n左右で個別に温度設定ができるほか、睡眠解析技術「Sleep Cycle」と連携して就寝中の温度を自動調整する機能も搭載しています。Matter規格に対応しており、主要なスマートホームプラットフォームから操作可能です。","importance":5},{"title":"おい、 Mutation Test をやれ。テスト品質を、測るために","url":"https://zenn.dev/mizchi/articles/mutation-test-quality","source":"Hatena","published_at":"2026-11-17 18:59","genre":"web","genre_label":"Web開発・言語","headline":"テスト品質を担保するミューテーションテストの重要性","summary":"AIによるコード生成が普及する中、カバレッジ指標だけでは担保できないテスト品質を測る手法として「ミューテーションテスト」が注目されています。ソースコードを意図的に書き換えてテストが検知できるかを確認することで、テストコード自体の品質を保証します。\n\n単純な分岐カバレッジは一定以上で費用対効果が低下しますが、ミューテーションテストはデッドコードの発見やテストの抜け漏れを可視化するのに有効です。テストのためのテストを減らし、実効性の高いテストスイートを構築するための強力なアプローチとして推奨されます。","importance":6},{"title":"エージェントの自律性を上げると、何が得られて何を失うか —— 助言・承認付き実行・自律実行を実測する","url":"https://zenn.dev/enterprise_ai/articles/1b1f34af88fb8f","source":"Zenn","published_at":"2026-11-17 15:51","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"AIエージェントの自律性とガバナンスのバランスを実測検証","summary":"AIエージェントの自律レベル（助言・承認・自律実行）を変えた際の挙動を実測。承認プロセスがセキュリティや運用に与える影響を検証し、比例的ガバナンスの重要性を説く。\n\n承認作業は回数よりも「読む量」が負担となり、形骸化しやすいことが判明。操作の審査は人ではなく仕組み（フックやモデルによる審査）に任せ、人は方針の決定や報告の確認に注力すべきであると結論づけている。企業導入におけるリスク管理の指針となる。","importance":8},{"title":"Microsoft FabricをGitに統合する ― ワークスペースとブランチの関係からAIエージェントを使った開発まで","url":"https://zenn.dev/headwaters/articles/e2aef1de50c368","source":"Zenn","published_at":"2026-11-17 23:57","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"Microsoft FabricのGit連携：ワークスペース管理とAI開発の統合","summary":"Microsoft FabricのワークスペースをGitリポジトリと同期し、バージョン管理やレビューを行うための構成を解説。アイテム定義のファイル化により、ローカルエディタやAIエージェントによるFabric開発が可能になるメリットを説明しています。\n\nワークスペースとGitブランチの対応関係や、同期の仕組み、データは保存されずメタデータのみが管理される仕様など、実運用上の注意点を網羅。Fabric CLIと組み合わせることで、AIエージェントを活用したモダンなデータ開発環境を構築するためのガイドラインとなっています。","importance":7},{"title":"スマホ内蔵のセンサーを使って周辺光取得を試す","url":"https://zenn.dev/aldagram_tech/articles/f7b57935e31070","source":"Zenn","published_at":"2026-11-17 09:37","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"スマホセンサーを活用した周辺光取得の実装調査","summary":"アプリのユーザー体験向上のため、スマートフォン内蔵センサーを用いた周辺光取得の実装調査を行いました。Androidでは標準のSensorManagerでTYPE_LIGHTセンサーから直接ルクス値を取得可能ですが、iOSではセンサーへの直接アクセスが制限されているため、カメラ機能やARKitを用いた推定値の利用が現実的です。\n\n本記事では、Compose Multiplatformを用いてAndroidとiOS双方で周辺光を取得する実装方針を解説しています。OSごとに単位や取得方法が異なるため、共通コードで生の値を扱い、UI表示用の正規化処理をOSごとに分ける設計を採用しています。","importance":5},{"title":"mise + gh skill で、dotfiles から Agent Skills を管理する","url":"https://zenn.dev/dress_code/articles/30bd78e1a67f87","source":"Zenn","published_at":"2026-11-17 12:00","genre":"web","genre_label":"Web開発・言語","headline":"miseとgh skillを活用したdotfilesによるAgent Skills管理","summary":"開発環境の管理ツール「mise」と「dotfiles」を組み合わせ、Claude CodeやCursorで利用する「Agent Skills」を効率的に管理する手法を紹介しています。以前はスクリプトでファイルを生成していましたが、管理の複雑化を避けるため、スキルを別リポジトリに切り出し、miseのタスク機能を通じて一元管理する構成へ移行しました。\n\nこの構成により、会社固有の規約を分離しつつ、新しい環境へのセットアップを「make mise」コマンド一つで完結できるようになりました。CursorがClaudeのスキルディレクトリを読み込める仕様を活かし、ツール間の互換性を保ちながら運用を簡素化しています。","importance":6},{"title":"毎月6,000 AI Agentsを捌くためにキーボードを捨てた話","url":"https://zenn.dev/andoshin11/articles/ba68b39ef9a8ce","source":"Hatena","published_at":"2026-11-17 15:39","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"月6,000セッションを捌くAIエージェント開発環境の構築術","summary":"大量のAIエージェントを並列運用する開発環境において、認知負荷と意思決定コストを極限まで削減する手法を解説。Orca ADEとClaude Codeを活用した自動化事例を紹介する。\n\nタスク進捗の可視化や、AIからの質問に対する自動検知・回答提案システムを構築し、開発速度を劇的に向上させた。AIに指示するコストを減らし、人間が判断に集中できる環境を整えるための具体的なプラグイン開発やプロンプト設計が示されている。","importance":8},{"title":"Apple、自立型AIエージェントによる情報漏洩やプライバシー侵害のリスクに対し、macOS 27.3 Golden Gate Beta 2で、フルディスクアクセスの細分化やアプリのアクセス許可の明示化などを開始。","url":"https://applech2.com/archives/20261117-apple-strengthens-macos-security-against-risks-from-ai-agents.html","source":"Hatena","published_at":"2026-11-17 16:32","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"macOS 27.3 Beta 2でAIエージェントの権限を細分化","summary":"Appleは、自立型AIエージェントによるプライバシー侵害リスクを低減するため、macOS 27.3 Golden Gate Beta 2にてフルディスクアクセスの細分化とアクセス許可の明示化を開始しました。\n\n新たに「デバイス制御」と「データアクセス」のAPIを追加し、フルディスクアクセス権を要求せずとも特定のフォルダや機能のみへのアクセスを可能にします。アプリごとのアクセス許可の可視性向上や、都度確認オプションの追加により、ユーザーが自身のデータをより細かく制御できる環境を提供します。","importance":7},{"title":"フロントエンドの logic と UI は、エージェントの責任範囲で分けられるのか","url":"https://zenn.dev/xtm_blog/articles/20261116-fd1702b0ba06cd","source":"Zenn","published_at":"2026-11-17 08:00","genre":"web","genre_label":"Web開発・言語","headline":"AIエージェント開発におけるフロントエンド実装の工程分割と責任範囲","summary":"AIエージェントが自律的に開発を行う基盤において、フロントエンド実装を効率的に分割・実行するための試行錯誤を記録しています。全体を通しで実行すると時間がかかりすぎるため、工程を分割して個別に実行する手法を検討しました。\n\nしかし、フロントエンドはバックエンドの完成を待たないと評価できないという依存関係があり、機械的な判定だけではテスト失敗の原因切り分けが困難であるという課題が浮き彫りになりました。各工程が「自分で評価できて責任を負えるものだけを持つ」という物差しを導入し、エージェントの自律性を高める設計を模索しています。","importance":6},{"title":"LLM に別の LLM の重みを書き換えさせる Weight-Space Programming を、Claude で試してみた","url":"https://zenn.dev/flinters_blog/articles/d0e738719e0054","source":"Zenn","published_at":"2026-11-17 12:00","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"LLMの重みを直接書き換えるWeight-Space Programmingの検証","summary":"MIT CSAILが発表した「Weight-Space Programming」は、LLMの重みを別のLLMエージェントに直接書き換えさせる手法です。ファインチューニングやプロンプトエンジニアリングに続く第3のモデル調整手法として注目されていますが、初期の成果には評価の分かれる側面もあります。\n\n筆者は実際にClaudeを用いてQwenの重み書き換えを試行し、モデルの振る舞いが変化することを確認しました。また、本記事ではこの手法の解説に加え、OpenAIのRealtime APIを活用した「発表の聞き役・相槌役」を行うAIエージェントの自作事例についても紹介しています。","importance":8},{"title":"65,535時間で死ぬSSDと死にかけた情シスの話","url":"https://zenn.dev/bellx2/articles/9acdc81630b72b","source":"Zenn","published_at":"2026-11-17 15:14","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"通電時間65,535時間で発症するSSDファームウェアのバグ","summary":"Micron製SSDにおいて、通電時間が65,535時間を超えるとI/Oが極端に遅延するファームウェアの不具合が発生。SMART情報が正常なままシステムがハングする深刻な障害事例を報告する。\n\n障害は同時期導入のSSDで一斉に発生し、ネットワーク障害と誤認しやすい症状を呈した。非公式の修正ファームウェアによる対処法や、iostatを用いたディスクごとの遅延確認方法など、情シス担当者にとって極めて有益なトラブルシューティングの記録である。","importance":7},{"title":"Breaking change: Japanese Calendar minimum supported date corrected - .NET","url":"https://learn.microsoft.com/en-us/dotnet/core/compatibility/globalization/11/japanese-calendar-min-date","source":"Hatena","published_at":"2026-11-17 09:59","genre":"web","genre_label":"Web開発・言語","headline":".NET 11における日本暦の最小サポート日付の変更","summary":".NET 11において、JapaneseCalendarクラスの最小サポート日付が「1868-09-08」から「1868-10-23」へ変更されました。これはUnicode CLDRデータの更新と、明治時代の開始日に関する歴史的正確性の向上を反映したものです。\n\nこの変更により、1868年9月8日から10月23日までの日付は無効として扱われるようになります。該当する日付を扱うコードに依存している場合は修正が必要となるため、開発者は注意が必要です。","importance":5},{"title":"MCP で AI に電話を持たせて、音声 AI をテストする","url":"https://zenn.dev/genax_corp/articles/20260910-mcpcon-telephone-mcp","source":"Zenn","published_at":"2026-11-17 10:47","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"MCPを活用したAIによる電話応対の自動テスト手法","summary":"コンタクトセンター向け音声AI「X-Ghost」の品質を担保するため、MCP（Model Context Protocol）を用いてAIに電話をかけさせる自動テスト基盤を構築しました。従来の「投げて返り値を見る」テストが困難な電話応対において、AIが実際に電話をかけ、会話を通じて応対の適切さを判断します。\n\n設計の肝は、MCPサーバーを介してAIに電話操作権限を渡し、リアルタイムの文字起こしテキストを推論モデルに読み込ませる点です。本番環境と同じ電話回線を通すことで、音声認識やネットワークを含めたEnd-to-Endのテストを実現しています。","importance":8},{"title":"PodmanのアーキテクチャとDockerとの違い【前編】","url":"https://zenn.dev/1stscratch/articles/27ce09315bfc6d","source":"Zenn","published_at":"2026-11-17 12:14","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"PodmanのDaemonless構造とDockerとのアーキテクチャ比較","summary":"PodmanはDockerと互換性のあるCLIを持ちつつ、中央管理デーモンを常駐させない「Daemonless」構造を採用しています。Dockerがクライアント・サーバー型でデーモンに依存するのに対し、Podmanはコマンド実行時にOCI Runtimeを直接呼び出すため、デーモンの稼働状態に左右されずコンテナを操作可能です。\n\nこの構造の違いにより、PodmanはRootless実行やPod管理において柔軟性を発揮します。ただし、Docker Daemonへの接続を前提としたツールはそのまま動作しない場合があるため、移行時にはアーキテクチャの違いを理解しておく必要があります。","importance":7},{"title":"ブラウザ上でWindows 98向けソフトのオリジナル実行ファイルが動作するエミュレーター「Wine-Assembly」","url":"https://gigazine.net/news/20261117-wine-assembly/","source":"Hatena","published_at":"2026-11-17 19:53","genre":"web","genre_label":"Web開発・言語","headline":"ブラウザ上でWindows 98を再現するWasmエミュレーター「Wine-Assembly」","summary":"Webブラウザ上で動作するWindows 98エミュレーター「Wine-Assembly」が公開されました。OSイメージやソースポートを使用せず、WebAssembly Textで記述されたクライアントサイドのみで動作する点が特徴です。\n\nマウスやタッチ操作に対応し、メモ帳やソリティア、Diabloなどの懐かしいアプリやゲームがブラウザ上でそのまま実行可能です。設定やスコアはブラウザ内にローカル保存されるため、手軽に当時の環境を体験できるユニークなプロジェクトとなっています。","importance":4}]};
